const items = $input.all();
const searchResults = items[0].json.items || [];
const competitorName = $node['入力データ設定'].json.competitor_name;

const results = [];

searchResults.forEach((item, index) => {
  try {
    const url = new URL(item.link);
    const domain = url.hostname.replace('www.', '');
    const title = item.title || '';
    const snippet = item.snippet || '';

    let relevanceScore = 0;
    const lowerCompetitor = competitorName.toLowerCase();
    const lowerTitle = title.toLowerCase();
    const lowerDomain = domain.toLowerCase();
    const lowerSnippet = snippet.toLowerCase();

    if (lowerTitle.includes(lowerCompetitor)) {
      relevanceScore += 50;
    }

    if (lowerDomain.includes(lowerCompetitor)) {
      relevanceScore += 30;
    }

    if (lowerSnippet.includes(lowerCompetitor)) {
      relevanceScore += 10;
    }

    if (lowerTitle.includes('公式') || lowerTitle.includes('official') || lowerSnippet.includes('公式')) {
      relevanceScore += 20;
    }

    relevanceScore += (5 - index) * 5;

    results.push({
      competitor_name: competitorName,
      domain: domain,
      full_url: item.link,
      title: title,
      snippet: snippet,
      relevance_score: relevanceScore,
      search_rank: index + 1
    });
  } catch (error) {
    console.error('URL解析エラー:', error, 'URL:', item.link);
  }
});

const sortedResults = results.sort((a, b) => b.relevance_score - a.relevance_score);

return sortedResults.slice(0, 3).map(item => ({ json: item }));

const items = $input.all();
const results = [];

items.forEach(item => {
  const htmlContent = item.json.data || item.json || '';
  const domain = item.json.domain;
  const competitorName = item.json.competitor_name;

  const advertiserIdPattern = /\/advertiser\/(AR[A-Z0-9]{20,})/gi;
  const advertiserIds = [];

  let match;
  while ((match = advertiserIdPattern.exec(htmlContent)) !== null) {
    const advertiserId = match[1];
    if (!advertiserIds.includes(advertiserId)) {
      advertiserIds.push(advertiserId);
    }
  }

  const namePattern = new RegExp(`${competitorName}`, 'gi');
  const hasCompanyName = namePattern.test(htmlContent);

  if (typeof htmlContent === 'object' && htmlContent.ad_creatives) {
    htmlContent.ad_creatives.forEach(ad => {
      if (ad.advertiser_id && ad.advertiser_name) {
        advertiserIds.push(ad.advertiser_id);
      }
    });
  }

  if (advertiserIds.length === 0) {
    const domainPattern = new RegExp(domain.replace(/\./g, '\\.'), 'gi');
    if (domainPattern.test(htmlContent)) {
      const dummyId = `AR${Date.now()}${Math.random().toString(36).substring(2, 8).toUpperCase()}`;
      advertiserIds.push(dummyId);
    }
  }

  advertiserIds.forEach(advertiserId => {
    const transparencyUrl = `https://adstransparency.google.com/advertiser/${advertiserId}`;

    results.push({
      competitor_name: competitorName,
      domain: domain,
      advertiser_id: advertiserId,
      transparency_center_url: transparencyUrl,
      has_company_name_match: hasCompanyName,
      search_success: true,
      extracted_from: 'html_parsing',
      timestamp: new Date().toISOString()
    });
  });

  if (advertiserIds.length === 0) {
    results.push({
      competitor_name: competitorName,
      domain: domain,
      advertiser_id: null,
      transparency_center_url: null,
      has_company_name_match: false,
      search_success: false,
      error_message: 'No advertiser ID found',
      timestamp: new Date().toISOString()
    });
  }
});

return results.map(item => ({ json: item }));

const items = $input.all();
const results = [];

items.forEach(item => {
  const data = item.json;

  if (data.result_status === 'success') {
    results.push({
      status: '✅ 成功',
      competitor_name: data.competitor_name,
      official_domain: data.official_domain,
      advertiser_id: data.advertiser_id,
      google_ads_transparency_url: data.google_ads_transparency_url,
      timestamp: data.discovery_timestamp,

      summary_report: `【競合広告URL発見】\n競合名: ${data.competitor_name}\n公式ドメイン: ${data.official_domain}\n広告主ID: ${data.advertiser_id}\nGoogle広告透明性センターURL: ${data.google_ads_transparency_url}\n発見日時: ${data.discovery_timestamp}`,

      next_actions: [
        '取得したURLで競合の広告データを確認',
        '広告クリエイティブの分析',
        'ターゲティング戦略の調査',
        '広告出稿期間の確認'
      ]
    });
  } else {
    results.push({
      status: '❌ 失敗',
      competitor_name: data.competitor_name,
      official_domain: data.official_domain || 'ドメイン取得失敗',
      error_message: data.error_message,
      manual_search_url: data.suggested_manual_search,
      timestamp: data.discovery_timestamp,

      summary_report: `【競合広告URL発見失敗】\n競合名: ${data.competitor_name}\n公式ドメイン: ${data.official_domain || '取得失敗'}\nエラー: ${data.error_message}\n手動検索URL: ${data.suggested_manual_search}\n実行日時: ${data.discovery_timestamp}`,

      alternative_actions: [
        '手動でGoogle Ads Transparency Centerを検索',
        '企業名のバリエーションで再検索',
        '関連子会社・ブランドでの検索',
        'SerpApiなど有料サービスの活用検討'
      ]
    });
  }
});

return results.map(item => ({ json: item }));
